        if (ind < n && ind < m)
            graph[a.charCodeAt(ind) - 97][b.charCodeAt(ind) - 97] = 1;
    }

    for (let i = 0; i < 26; i++) {
        if (exist[i] && !vis[i]) {
            let x = dfs(i, graph, vis, rec, ans);

            // Return empty string if a cycle is found
            if (!x) return "";
        }
    }

    // Reverse to get the correct topological order
    ans.reverse();
    return ans.join('');
}


